    ("perl net ssh", "`use Net::OpenSSH;\nmy $ssh = Net::OpenSSH->new($host, user => $u, key_path => $k);\nmy @out = $ssh->capture('uptime');` (!) — scripted remote runs (!) — or system('ssh', !) (!) — key auth not passwords (!)."),
