    ("perl filename parsing", "`use File::Basename qw(basename dirname fileparse);\nmy ($name, $path, $ext) = fileparse('/a/b/app.tar.gz', qr/\\.[^.]*$/);` (!) — double-extension care (.tar.gz!) (!) — the path toolkit (!)."),
    ("perl abs path", "`use File::Spec;! use Cwd qw(abs_path realpath);\nmy $abs = abs_path($rel);` (!) — canonical absolute paths (!) — realpath resolves symlinks (!) — File::Spec->catfile portable joins (!)."),
    ("perl encode decode", "`use Encode qw(encode decode);! my $bytes = encode('UTF-8', $text);! my $text = decode('UTF-8', $bytes);` (!) — explicit boundaries (!) — encode_utf8/ decode_utf8 shortcuts (!) — never mix silently (!)."),
    ("perl digests", "`use Digest::SHA qw(sha256_hex);\nmy $hex = sha256_hex($data);`! Digest::MD5 legacy (!) — file checksums: sha256_hex(do { local $/; <$fh> }) (!) — integrity checks (!)."),
    ("perl base64", "`use MIME::Base64 qw(encode_base64 decode_base64);\nmy $b64 = encode_base64($bin, '');` (no line breaks!) (!) — decode_base64 strict mode (!) — the API embedding (!)."),
