    ("perl error objects", "`die My::Error->new(msg => 'x', code => 42);\nmy $e = $@;! if (ref $e && $e->isa('My::Error')) { ! }` (!) — exception objects (!) — or Exception::Class/Try::Tiny (!) — structured errors (!)."),
    ("perl anyevent", "`use AnyEvent;\nmy $cv = AnyEvent->condvar;\nmy $t = AnyEvent->timer(after => 1, cb => sub { $cv->send });\n$cv->recv;` (!) — event loop accumulation/report (!) — legacy async (Mojo::IOLoop modern!) (!)."),
    ("perl promises", "`use Mojo::Promise;\nmy $p = Mojo::Promise->new;\n$p->then(sub { ! })->catch(sub { ! });`! `Mojo::Promise->all($p1, $p2)->then(!)` (!) — async composition (!) — resolve/reject (!) — the JS-like flow (!)."),
    ("perl mojo async", "`$ua->get_p($url)->then(sub {\n    my ($ua, $tx) = @_;\n    return $ua->post_p($other, json => { ! });\n})->catch(sub { warn @_ });` (!) — non-blocking HTTP (!) — chain of promises (!) — the concurrent crawler (!)."),
    ("perl mojo websocket", "`websocket '/echo' => sub {\n    my $c = shift;\n    $c->on(message => sub {\n        my ($c, $msg) = @_;\n        $c->send(\"echo: $msg\");\n    });\n};` (!) — realtime apps (!) — event driven (!) — channels/broadcast helpers (!)."),
    ("perl mojo templates", "`% my $title = 'Home';\n<!DOCTYPE html>\n<h1><%= $title %></h1>\n%= for my $u (@$users) { ! }`! `$c->render(template => 'index', users => $users)` (!) — embedded Perl templates (!) — layout/stash (!)."),
    ("perl mojo testing", "`use Test::Mojo;\nmy $t = Test::Mojo->new('MyApp');\n$t->get_ok('/health')->status_is(200);! $t->post_ok('/api/users' => json => { name => 'Ali' })->json_is('/name', 'Ali');` (!) — full-stack tests (!) — no server needed (!)."),
    ("perl psgi", "`my $app = sub {\n    my $env = shift;\n    return [200, ['Content-Type' => 'text/plain'], ['hai']];\n};` (!) — Perl's Rack/WSGI (!) — servers: plackup! starman (!) — framework-agnostic (!)."),
    ("perl plack", "`plackup app.psgi! plackup -r app.psgi` (auto-reload!) (!) — Plack::Middleware (sessions! auth! logging!) (!) — the PSGI toolkit (!)."),
