    ("perl mojo commands", "`app->commands->add(report => sub { ! });`! `perl app.pl report` (!) — CLI subcommands in the same app (!) — cron tasks share code (!) — the unified tool (!)."),
    ("perl carton", "`carton install! carton exec perl app.pl` (!) — bundles exact versions (vendor/cache!) (!) — cpanfile.lock committed (!) — the reproducible deps (!) — like bundle for Perl (!)."),
    ("perl cpanfile", "`requires 'Mojolicious', '>= 9.0';! on test => 'Test::More';! on develop => 'Perl::Critic';` (!) — dependency declaration (not execution!) (!) — carton/cpanm reads it (!) — the manifest (!)."),
    ("perl dist packaging", "`dzil new My-Dist! dzil build! dzil release` (Dist::Zilla!) (!) — or minilla/minil (!) — generate + test + upload chain (!) — PAUSE account for indexing (!)."),
    ("perl pp packaging", "`pp -o app app.pl` (!) — packed executable (perl + modules embedded!) (!) — PAR::Packer (!) — big binaries but zero-dependency deploy (!) — or fatpacked single file (!)."),
    ("perl fatpack", "`fatpack pack app.pl > app ! chmod +x app` (!) — single script with modules inlined (!) — App::FatPacker (!) — great for small tools (!)."),
    ("perl windows strawberry", "Strawberry Perl = batteries-included Windows build (!) — cpanm works out of the box (compiler included!) (!) — PATH setup (!) — for Linux-target tools prefer WSL (!)."),
    ("perl shebang portability", "`#!/usr/bin/env perl` (portable!) (!) — env avoids hardcoded path (!) — cmd/runners: perl script.pl (!) — Strawberry uses perl.exe association (!)."),
    ("perl argv encoding", "argv comes as BYTES (!) — decode explicitly: decode('UTF-8', $ARGV) (!) — `use open ':std', ':encoding(UTF-8)'` helps stdio (!) — the encoding trap (!)."),
