    ("perl sort unicode", "sort is codepoint order by default (!) — locale collation: `use Unicode::Collate; my $c = Unicode::Collate->new; sort { $c->cmp($a, $b) } @words` (!) — glibc locale sort also (!)."),
    ("perl number parsing", "`my $n = $str + 0;` coerces leading-number (!) — Look::s(:) for grouping (!) — validation: /^\\d+$/ before use (!) — never trust input numbers (!)."),
    ("perl floating point", "0.1 + 0.2 != 0.3 (!) — money: integer cents or Math::BigFloat (!) — stringify rounds to 15 digits (!) — the universal float rules (!)."),
    ("perl bignum", "`use bignum;! use Math::BigInt;! use Math::BigFloat;` (!) — arbitrary precision (slow!) (!) — financial/deep math (!) — or use integer for coin math (!)."),
    ("perl bitwise ops", "`$a & $b! $a | $b! $a ^ $b! ~$a! $a << 2! $a >> 1` (!) — & | ^ on integers (!) — vec() for bit vectors (!) — the systems programming (!)."),
    ("perl pack unpack", "`my $bin = pack('N', 0x12345678);! my $n = unpack('N', $bin);` (!) — N big-endian 32! V little! C byte! a string (!) — binary protocols (!)."),
    ("perl binary files", "`open(my $fh, '<:raw', $file) or die $!;\nread($fh, my $buf, 4096);`! sysread for unbuffered (!) — :raw layer no translation (!) — pack/unpack parse (!) — the binary toolbox (!)."),
    ("perl vec", "`vec($bits, $i, 1) = 1;! say vec($bits, $i, 1);` (!) — bit vectors compact (bitset!) (!) — width 1/2/4/8/16/32 (!) — old-school but lean (!)."),
    ("perl sprintf advanced", "`sprintf('%05d', 42)! sprintf('%-10s|', $s)! sprintf('%x', 255)! sprintf('%b', 5)! sprintf('%.3g', $f)` (!) — zero pad! justify! hex! binary (!) — the formatting reference (!)."),
    ("perl flock", "`open(my $fh, '>', '/var/lock/app.lock') or die $!;\nflock($fh, LOCK_EX | LOCK_NB) or die 'already running\\n';` (!) — single-instance cron guard (!) — LOCK_NB = fail fast (!) — lock released on close/crash (OS!) (!)."),
    ("perl atomic writes", "Write temp + rename: `my $tmp = \"$file.tmp.$$\";\nopen(my $fh, '>', $tmp) or die $!;\nprint $fh $data;\nclose $fh;\nrename $tmp, $file or die $!;` (!) — rename atomic on same fs (!) — no torn files (!)."),
    ("perl fsync durability", "`use IO::Handle;! $fh->flush;! $fh->sync;` (!) — flush = push to OS! sync = to disk (!) — atomic replace still needs dir fsync for crash safety (!) — the durability ladder (!)."),
    ("perl symlinks", "`symlink $target, $link or die $!;! readlink($link);! -l $path` (!) — create/read links (!) — broken link detection (!) — find -type l equivalents (!)."),
    ("perl hardlinks", "`link($old, $new) or die $!;! (stat($f))[3]` (link count!) (!) — same inode data (!) — or File::Copy fallback (!) — backup strategies (!)."),
    ("perl stat details", "`my ($dev, $ino, $mode, $nlink, $uid, $gid, $size, $atime, $mtime, $ctime) = stat($f);` (!) — lstat for links (!) — -M days since mtime (!) — the metadata (!)."),
    ("perl timegm", "`use Time::Piece;\nmy $epoch = Time::Piece->strptime('2026-10-17 10:00', '%Y-%m-%d %H:%M')->epoch;` (!) — parse to epoch (!) — gmtime/localtime (!) — timezone via TZ env or DateTime (!)."),
    ("perl autodie", "`use autodie;` (!) — open/close/rename FAIL = exception (no or die needed!) (!) — per-function: autodie qw(open) (!) — the safety upgrade (!)."),
    ("perl warnings categories", "`use warnings FATAL => 'all';` (warnings become fatal!) (!) — no warnings 'uninitialized' for specific (!) — the strictness dial (!)."),
    ("perl each pitfall", "each %hash shares ONE iterator per hash (!) — nested/mixed loops skip items (!) — reset via keys/values first (!) — or avoid each in loops (!)."),
    ("perl values keys order", "keys/values = same order (random per process!) (!) — sort if stable output needed (!) — PERL_HASH_SEED for reproducibility (!) — the gotcha (!)."),
