    ("lua numbers", "5.3+: integers (64-bit!) + floats (!) — `/` always float! `//` integer division (!) — math.floor/ceil (!) — no overflow surprises (wraps int64!) (!)."),
    ("lua strings", "Immutable byte strings (!) — 'a' or \"b\" identical! [[long strings]] (!) — `..` concatenation (!) — #s = length (bytes!) (!) — utf8 lib for chars (!)."),
    ("lua string library", "`string.upper(s)! string.lower(s)! string.sub(s, 2, 5)! string.rep('ab', 3)! string.reverse(s)! string.len(s)` (!) — s:upper() method syntax (!) — 1-based indexes (!)."),
    ("lua string format", "`string.format('%s=%d (%.2f)', k, n, x)`! `('%5d'):format(v)` (!) — printf-style (!) — %q for quoted (!) — the formatting tool (!)."),
