    ("lua pattern captures", "`local y, m, d = ('2026-10-17'):match('(%d+)-(%d+)-(%d+)')`! `s:gsub('(%w+)%s+(%w+)', '%2 %1')` (!) — () captures (!) — %1..%9 in gsub (!) — the extraction (!)."),
    ("lua gsub", "`s:gsub('foo', 'bar')! s:gsub('%s+', ' ')! s:gsub('(%d+)', function(n) return n * 2 end)` (!) — returns new + count (!) — function replacements (!) — the text munger (!)."),
    ("lua tables", "`local t = {}! t.name = 'Ali'! t['age'] = 30! t[1] = 'first'` (!) — the ONLY data structure (arrays! maps! objects!) (!) — 1-based arrays (!) — nil = absent (!)."),
    ("lua table literals", "`local t = { name = 'Ali', 10, 20, 'x' }` (!) — mixed keys + positional (!) — t[1] = 10! t.name = 'Ali' (!) — trailing commas ok (!) — nested literals (!)."),
    ("lua table length", "`#t` for sequences (!) — holes = undefined behavior (!) — use table.pack/n for mixed (!) — count keys: loop pairs (!) — the caveat (!)."),
    ("lua table insert remove", "`table.insert(t, 'x')! table.insert(t, 1, 'first')! local last = table.remove(t)! table.remove(t, 1)` (!) — shift others (!) — O(n) at front (!) — the array ops (!)."),
    ("lua table sort", "`table.sort(t)! table.sort(t, function(a, b) return a.age < b.age end)` (!) — in place! default < (!) — comparator must be strict (!) — the ordering (!)."),
    ("lua table concat", "`table.concat(t, ', ')! table.concat(t, '', 2, #t)` (!) — strings/numbers only (!) — the join builtin (!) — slice with i, j args (!)."),
    ("lua table unpack", "`local a, b, c = table.unpack(t)! f(table.unpack(args))` (!) — 5.1: unpack (global!) — spread into varargs (!) — with range: unpack(t, 2, 4) (!)."),
    ("lua pairs", "`for k, v in pairs(t) do print(k, v) end` (!) — ALL keys (arbitrary order!) (!) — the general iteration (!) — order changes between runs (!)."),
    ("lua ipairs", "`for i, v in ipairs(arr) do print(i, v) end` (!) — sequential 1..n (stops at nil!) (!) — arrays only (!) — the safe array loop (!)."),
    ("lua next", "`local k, v = next(t)`! `while true do k, v = next(t, k); if k == nil then break end end` (!) — pairs manual (!) — stateless iteration (!)."),
    ("lua metatables", "`local mt = { __index = function(t, k) return 0 end }\nsetmetatable(t, mt)! getmetatable(t)` (!) — behavior overrides (!) — the OOP foundation (!) — the metatable magic (!)."),
    ("lua metamethods", "__index! __newindex! __call! __add! __eq! __lt! __tostring! __len! __concat! __close (5.4!) (!) — the full hook table (!) — operators are methods (!)."),
    ("lua index newindex", "__index = table or function (reads missing keys!) (!) — __newindex intercepts writes (!) — defaults! proxies! readonly tables (!) — the interception pair (!)."),
    ("lua callable tables", "`mt.__call = function(self, a) return a * 2 end\nsetmetatable(t, mt)! t(5) # -> 10`! — function-like tables (!) — callable objects (!) — the syntactic sugar (!)."),
    ("lua tostring __tostring", "`mt.__tostring = function(self) return 'Point(' .. self.x .. ')' end! print(t)` (!) — print human form (!) — vs __name (metatable field!) (!)."),
    ("lua oop class", "`local Point = {}\nPoint.__index = Point\nfunction Point.new(x, y)\n  return setmetatable({ x = x, y = y }, Point)\nend`! `local p = Point.new(1, 2)` (!) — tables + metatables = OOP (!)."),
    ("lua oop inheritance", "`local Base = {}! local Child = setmetatable({}, { __index = Base })\nChild.__index = Child` (!) — chain of __index (!) — method lookup walks up (!) — override by defining own (!)."),
    ("lua oop colon", "`function Point:distance()\n  return math.sqrt(self.x^2 + self.y^2)\nend! p:distance()` (!) — colon = self implicit (!) — definition vs call (!) — the method syntax (!)."),
    ("lua closures", "`local function counter()\n  local n = 0\n  return function() n = n + 1; return n end\nend` (!) — capture upvalues (!) — per-closure state (!) — the factory pattern (!)."),
    ("lua varargs", "`function f(...)\n  local args = table.pack(...)\n  print(args.n, args[1])\nend`! `local function sum(...) local s = 0 for _, v in ipairs({...}) do s = s + v end return s end` (!) — ... collects (!) — select('#', ...) count (!) — 5.1 select !)."),
    ("lua functions first class", "`local ops = { add = function(a, b) return a + b end }! ops.add(1, 2)! local f = print; f('hai')` (!) — functions are values (!) — pass/return/store (!) — the functional base (!)."),
    ("lua multiple returns", "`local function minmax(t) return math.min(table.unpack(t)), math.max(table.unpack(t)) end! local lo, hi = minmax({3, 1, 2})` (!) — last-position expand (!) — parens truncate ((f())!) (!) — select handles middle (!)."),
    ("lua tail calls", "`return f(x)` in tail position = true tail call (no stack growth!) (!) — recursion to iteration (!) — `return (f(x))` BREAKS it (paren!) (!) — the efficiency note (!)."),
    ("lua conditionals", "`if x > 5 then ! elseif x > 2 then ! else ! end` (!) — then/end keywords (!) — falsy = nil and false ONLY (0 and '' truthy!) (!) — and/or expressions (!)."),
    ("lua loops", "`while cond do ! end! repeat ! until cond` (runs once!) (!) — numeric: `for i = 1, 10, 2 do ! end`! generic: `for k, v in pairs(t)` (!) — break works; no continue (goto!) (!)."),
    ("lua break goto", "`for i = 1, 10 do if i % 2 == 0 then goto continue end ! ::continue:: end` (!) — goto labels (!) — simulate continue (!) — local scope limits (!)."),
    ("lua local scope", "`local x = 5` block-scoped (!) — globals live in _G (typos become globals — always local!) (!) — do blocks create scopes (!) — the discipline (!)."),
    ("lua require modules", "`local json = require('json')`! `require('lib.utils')` (dots = dirs!) (!) — caches in package.loaded (!) — the module system (!)."),
    ("lua module pattern", "`-- mymod.lua\nlocal M = {}\nfunction M.greet(name) return 'Hai ' .. name end\nreturn M`! `local m = require('mymod')` (!) — return a table (!) — the module idiom (!)."),
    ("lua package path", "`package.path = './?.lua;' .. package.path`! `package.cpath` for C libs (!) — print(package.path) debug (!) — LUA_PATH env (!) — the resolution order (!)."),
    ("lua errors", "`error('boom')! error({ code = 404 }, 2)` (!) — level 2 = blame caller (!) — errors are values (!) — pcall catches (!) — the throw (!)."),
    ("lua pcall", "`local ok, err = pcall(function() risky() end)! if not ok then print('failed: ' .. tostring(err)) end` (!) — protected call (!) — returns ok + results/error (!) — the try/catch substitute (!)."),
    ("lua xpcall", "`local ok, err = xpcall(risky, function(e) print(debug.traceback(e)) return e end)`! xpcall(f, handler, ...) (!) — traceback on error (!) — the debuggable catch (!)."),
    ("lua assert", "`local f = assert(io.open('f.txt'), 'cannot open')\nassert(type(x) == 'number', 'x must be number')` (!) — returns args if truthy (!) — shortens pcall patterns (!) — the guard (!)."),
    ("lua coroutines", "`local co = coroutine.create(function() coroutine.yield(1) return 2 end)! print(coroutine.resume(co)) # true 1! print(coroutine.resume(co)) # true 2` (!) — cooperative threads (!) — yield/resume (!) — the async base (!)."),
    ("lua coroutine patterns", "Producer/consumer: wrap in a function returning an iterator (!) — co.wrap (5.4!) (!) — status: suspended/running/dead (!) — the stream generator (!)."),
    ("lua io read write", "`local f = io.open('out.txt', 'w')! f:write('hello\\n')! f:close()! local f2 = io.open('in.txt')! local line = f2:read('l')` (!) — 'l' line! 'a' all! 'n' number (!) — check open for nil (!)."),
    ("lua io lines", "`for line in io.lines('data.txt') do print(line) end`! `for n in io.lines('nums.txt', 'n') do ! end` (!) — streams lines (!) — format per iteration (!) — the log reader (!)."),
    ("lua os execute", "`local ok = os.execute('ls -la')! local exit_ok = os.execute('make')` (!) — returns status (5.2+!) (!) — io.popen for output (!) — the shell bridge (!)."),
