    ("lua os time date", "`os.time()! os.date('%Y-%m-%d %H:%M')! os.date('*t', os.time())! os.time({ year = 2026, month = 10, day = 17 })` (!) — epoch seconds (!) — *t = table (!) — os.clock for CPU (!)."),
    ("lua cli args", "`local args = { ... }` (!) — script args after the file (!) — or the global arg table: arg[1]! arg[0] = script (!) — arg[-1] = interpreter (!)."),
    ("lua math library", "`math.floor! math.ceil! math.abs! math.max! math.min! math.sqrt! math.huge! math.pi! math.random(1, 6)! math.fmod` (!) — trig too (!) — the standard math (!)."),
    ("lua random", "`math.randomseed(os.time())! math.random() -- [0, 1)! math.random(10)! math.random(1, 100)` (!) — seed once at startup (!) — not crypto (use luarocks crypto libs!) (!)."),
    ("lua bitwise", "5.3+: `a & b! a | b! a ~ b! ~a! a << 2! a >> 1` (!) — 5.1/5.2: bit32 library (!) — integer semantics (!) — the systems work (!)."),
    ("lua integer float", "`3 / 2 = 1.5! 3 // 2 = 1! 7 // 2.0 = 3.0` (!) — tostring shows 1.0 vs 1 (!) — math.type(x) (!) — the numeric duality (!)."),
    ("lua lpeg", "`local lpeg = require('lpeg')\nlocal digit = lpeg.R('09')\nlocal number = digit^1 / tonumber`! `number:match('123')` (!) — PEG parsing (no regex limits!) (!) — fast + composable (!) — the text parsing power tool (!)."),
    ("lua lpeg grammars", "`local grammar = lpeg.P({\n  'expr',\n  expr = lpeg.Ct(term * (lpeg.S('+-') * term)^0),\n  term = digit^1 / tonumber,\n})` (!) — full grammar in a table (!) — captures Ct/C/Cg (!) — JSON/CSV parsers written in it (!)."),
    ("lua json", "`local json = require('cjson')` (fast C!) `require('dkjson')` (pure Lua!) (!) — json.encode(data)! json.decode(str) (!) — pure Lua works everywhere (!)."),
