    ("lua socket", "`local socket = require('socket')! local tcp = assert(socket.tcp())! tcp:connect('example.com', 80)! tcp:send('GET / HTTP/1.0\\r\\n\\r\\n')! local data = tcp:receive('*a')` (!) — the network layer (!)."),
