    ("lua uuid", "`local uuid = require('uuid')`! `uuid()` or uuid.new() (!) — luarocks install uuid (!) — v4 random (!) — DB/keys (!)."),
    ("lua date", "`os.date`/`os.time` for basics (!) — `require('date')` (luadate!) for parsing/arith: date('%Y-%m-%d'):adddays(7) (!) — or lua-cosmo (!)."),
    ("lua logging", "Simple: `local function log(level, msg) print(os.date('[%H:%M:%S] ') .. level .. ' ' .. msg) end` (!) — or lua-log (log4j-like!) (!) — levels + context (!)."),
    ("lua argparse", "`local parser = argparse()! parser:argument('name')! parser:option('--count', 'times'):convert(tonumber)! local args = parser:parse()` (!) — CLI parsing with help (!) — luarocks argparse (!)."),
    ("lua penlight", "`local pl = require('pl.utils')` (!) — the extended stdlib (path! f-string! stringx! tablex! class!) (!) — pl.path.join! pl.stringx.split (!) — batteries for Lua (!)."),
    ("lua busted", "`describe('User', function()\n  it('greets', function()\n    assert.are.equal('hai', greet('Ali'))\n  end)\nend)`! `busted` runs spec/ (!) — the test framework (!) — luarocks busted (!)."),
