    ("lua profiler", "`luarocks install luaprofiler`! or `require('profile')` (!) — time per function (!) — or debug.sethook sampling (!) — find hot paths (!)."),
    ("lua perf patterns", "Localize globals in hot loops (local math = math!) (!) — avoid string ops in loops (!) — table reuse not recreate (!) — LuaJIT: JIT-friendly types (no mixed!) (!)."),
    ("lua gc", "`collectgarbage('count')! collectgarbage('collect')! collectgarbage('step')` (!) — generational mode: collectgarbage('generational') (!) — tune incremental params (setpause/setstepmul!) (!)."),
    ("lua weak tables", "`local cache = setmetatable({}, { __mode = 'v' })` (!) — weak keys ('k'!) weak values ('v'!) (!) — caches that auto-free (!) — GC controls removal (!)."),
    ("lua finalizers", "`setmetatable(obj, { __gc = function(o) close(o) end })` (!) — runs at collection (!) — mark first (setmetatable time!) (!) — resource cleanup (!) — 5.4: __close for to-be-closed (!)."),
    ("lua sandboxing", "Fresh env + restricted libs: `local env = { print = print, math = math }\nlocal f = load(chunk, 'sandbox', 't', env)` (!) — remove debug/os/io (!) — the untrusted-code box (!)."),
    ("lua load", "`local f, err = load('return 1 + 2')`! `load(reader_function)! load(chunk, name, mode, env)` (!) — dynamic code (!) — 5.1: loadstring (!) — check err (!)."),
    ("lua environments", "5.2+: _ENV is the lookup table (!) — `local _ENV = { print = print }` scoped (!) — setfenv gone (5.1 legacy!) (!) — the global switch (!)."),
    ("lua dofile", "`dofile('config.lua')` (!) — runs file in current env (returns values!) (!) — vs require (caches!) (!) — config scripts idiom (!)."),
    ("lua luac bytecode", "`luac -o app.luac main.lua! lua app.luac` (!) — precompile (faster load!) (!) — same VM speed after (!) — strip debug: -s (!) — not encryption (obfuscation only!) (!)."),
    ("lua luajit", "LuaJIT = JIT-compiled Lua (5.1 compatible!) (!) — 2-50x faster in loops (!) — OpenResty uses it (!) — `luajit script.lua` (!) — the speed demon (!)."),
    ("lua luajit ffi", "`local ffi = require('ffi')\nffi.cdef[[int abs(int);]]\nlocal C = ffi.C! print(C.abs(-5))` (!) — call C directly (no bindings!) (!) — structs! arrays! (!) — LuaJIT's superpower (!)."),
    ("lua luajit perf", "JIT traces: avoid NYI (string.format in hot loops! pcall!) (!) — table.new/table.clear (FFI!) (!) — jit.v for IR debugging (!) — heat up loops before benchmarking (!)."),
    ("lua love2d intro", "`function love.draw() love.graphics.print('Hai', 400, 300) end` (!) — the 2D game framework (!) — love.update + love.draw loop (!) — conf.lua config (!) — the game jam king (!)."),
    ("lua love2d input", "`function love.keypressed(key) if key == 'escape' then love.event.quit() end end! function love.mousepressed(x, y, button) ! end` (!) — event callbacks (!) — love.keyboard.isDown in update (!)."),
