    ("lua neovim config", "`-- ~/.config/nvim/init.lua\nvim.opt.number = true! vim.opt.shiftwidth = 4! require('myplugin').setup({})` (!) — init.lua (not init.vim!) (!) — lua/ modules (!) — the editor platform (!)."),
    ("lua neovim keymaps", "`vim.keymap.set('n', '<leader>ff', function()\n  require('telescope.builtin').find_files()\nend, { desc = 'Find files' })` (!) — function keymaps (!) — desc for which-key (!) — the config glue (!)."),
    ("lua neovim api", "`vim.api.nvim_create_autocmd('BufWritePre', { callback = function() vim.lsp.buf.format() end })`! `vim.fn.expand('%:p')` (!) — the api/fn split (!) — autocmds + user commands (!)."),
    ("lua neovim plugins", "`{ 'nvim-telescope/telescope.nvim', dependencies = { 'nvim-lua/plenary.nvim' }, opts = {} }` (lazy.nvim!) (!) — spec tables (!) — lazy loading events (!) — the plugin manager (!)."),
    ("lua openresty", "nginx + LuaJIT: `location /api {\n  content_by_lua_block {\n    ngx.say('hai')\n  }\n}` (!) — Lua in the web server (!) — ngx.* API (!) — the high-perf gateway (!)."),
