    ("django template inheritance", "base.html: `<!DOCTYPE html>\n<html>\n<body>\n{% block content %}{% endblock %}\n</body>\n</html>`! child: `{% extends 'base.html' %}\n{% block content %} ! {% endblock %}` (!) — DRY layouts (!) — {% block %} slots + {{ block.super }} (!)."),
